    "summary": "The color change a third of the way up the Washington Monument is a twenty-year pause and three different quarries.",
    "point": {
      "at": {
        "lat": 38.88949,
        "lng": -77.03462
      },
      "triggerRadiusKm": 0.08,
      "place": "Washington Monument, Washington, D.C."
    },
    "category": "built",
    "format": "short",
